    last_by = "region"
    last_key: str | None = None
    for item in groups_raw:
        if not isinstance(item, dict) or set(item) != {
            "by", "key", "candidates",
        }:
            raise ValueError(_PRIORITY_MATRIX_ERROR)
        by = item["by"]
        key = item["key"]
        candidates_raw = item["candidates"]
